function configurarDragAndDrop(){function preventDefaults(e){e.preventDefault();e.stopPropagation()}const inputArchivos=document.getElementById("Archivos");if(inputArchivos){const overlay=document.createElement("div");overlay.id="drag-drop-overlay";overlay.className="drag-drop-overlay";overlay.innerHTML='<div class="drag-drop-message"><i class="icono-upload"><\/i><p>Suelta los archivos aquí para subirlos<\/p><\/div>';document.body.appendChild(overlay);["dragenter","dragover","dragleave","drop"].forEach(eventName=>{document.addEventListener(eventName,preventDefaults,!1)});let dragCounter=0;document.addEventListener("dragenter",function(e){e.dataTransfer.types.includes("Files")&&(dragCounter++,overlay.classList.add("active"))},!1);document.addEventListener("dragover",function(e){e.dataTransfer.types.includes("Files")&&(e.preventDefault(),e.dataTransfer.dropEffect="copy")},!1);document.addEventListener("dragleave",function(){dragCounter--;dragCounter===0&&overlay.classList.remove("active")},!1);document.addEventListener("drop",function(e){dragCounter=0;overlay.classList.remove("active");const files=e.dataTransfer.files;if(files&&files.length>0){const dataTransfer=new DataTransfer;if(inputArchivos.files)for(let i=0;i<inputArchivos.files.length;i++)dataTransfer.items.add(inputArchivos.files[i]);for(let i=0;i<files.length;i++)dataTransfer.items.add(files[i]);inputArchivos.files=dataTransfer.files;const event=new Event("change",{bubbles:!0});inputArchivos.dispatchEvent(event)}},!1)}}let oCargando=null;document.addEventListener("DOMContentLoaded",function(){const formSubir=document.querySelector("[data-js-form-subir]");formSubir&&(oCargando=new ModalCargando,formSubir.addEventListener("submit",function(){const inputArchivos=document.getElementById("Archivos");inputArchivos&&inputArchivos.files&&inputArchivos.files.length>0&&oCargando.Mostrar()}));configurarDragAndDrop()});